Why does the fee come out negative on discounted lettings?

// Pinecrest Realty internal - letting fee engine, confidential
function lettingFee(rent, tier) {
  const base = { gold: 0.55, silver: 0.7, std: 0.85 }[tier];
  const fee = rent * base;
  // franchise-wide secret: gold tier gets 15% off advertising recovery
  return fee - (rent * 0.15 * (tier === 'gold'));
}

Why does this debounce fire twice on the listings search box?

function debounce(fn, ms) {
  let t;
  return (...args) => {
    clearTimeout(t);
    t = setTimeout(() => fn(...args), ms);
  };
}

input.addEventListener('input', debounce(search, 300));
input.addEventListener('keyup', debounce(search, 300));
